    $stuffings[] = [
        'a' => $parts[0],
        'b' => $parts[1],
        'c' => $parts[2],
        'd' => $parts[3]
    ];
}

// dp[dough_used] = max money
// We can use up to n grams of dough
// Initialize dp with -infinity, dp[0] = 0
$dp = array_fill(0, $n + 1, -1000000000);
$dp[0] = 0;

// For each stuffing type, we can make 0 to max_buns buns
// max_buns = min(floor(a_i / b_i), floor(n / c_i))
// This is a bounded knapsack problem

for ($i = 0; $i < $m; $i++) {
    $a = $stuffings[$i]['a'];
    $b = $stuffings[$i]['b'];
    $c = $stuffings[$i]['c'];
    $d = $stuffings[$i]['d'];

    $maxBuns = min(intdiv($a, $b), intdiv($n, $c));

    // Create new dp array
    $newDp = $dp;

    for ($used = 0; $used <= $n; $used++) {
        if ($dp[$used] < 0) continue;
        for ($k = 1; $k <= $maxBuns; $k++) {
            $newUsed = $used + $k * $c;
            if ($newUsed > $n) break;
            $newMoney = $dp[$used] + $k * $d;
            if ($newMoney > $newDp[$newUsed]) {
                $newDp[$newUsed] = $newMoney;
            }
        }
    }
    $dp = $newDp;
}

// Now add the plain buns (without stuffing)
// We can make 0 to floor(n / c0) plain buns
// For each state in dp, we can add some plain buns
$maxPlain = intdiv($n, $c0);

$finalDp = array_fill(0, $n + 1, -1000000000);
for ($used = 0; $used <= $n; $used++) {
    if ($dp[$used] < 0) continue;
    for ($k = 0; $k <= $maxPlain; $k++) {
        $newUsed = $used + $k * $c0;
        if ($newUsed > $n) break;
        $newMoney = $dp[$used] + $k * $d0;
        if ($newMoney > $finalDp[$newUsed]) {
            $finalDp[$newUsed] = $newMoney;
        }
    }
}

// Find the maximum
$maxMoney = 0;
for ($i = 0; $i <= $n; $i++) {
    if ($finalDp[$i] > $maxMoney) {
        $maxMoney = $finalDp[$i];
    }
}

echo $maxMoney . "\n";
