<?php

function solve() {
    $input = explode("\n", trim(file_get_contents("php://stdin")));
    $line0 = explode(" ", trim($input[0]));
    $n = (int)$line0[0];
    $m = (int)$line0[1];
    $c0 = (int)$line0[2];
    $d0 = (int)$line0[3];

    $stuffings = [];
    for ($i = 1; $i <= $m; $i++) {
        $parts = explode(" ", trim($input[$i]));
        $a = (int)$parts[0];
        $b = (int)$parts[1];
        $c = (int)$parts[2];
        $d = (int)$parts[3];
        $stuffings[] = [$a, $b, $c, $d];
    }

    // dp[i][j] = max money using first i stuffings with j grams of dough remaining
    // We'll use dp[j] where j is dough used so far, or remaining. Let's use remaining dough.
    // Actually, let's use dp[i][dough_used] but dough_used can be up to n.
    // Alternatively, dp[i][dough_remaining]

    // Let's do: dp[i][r] = max profit using first i stuffings, with r grams of dough remaining
    // Initialize dp[0][r] = 0 for all r
    // For each stuffing i, we can make k buns of type i, where k is from 0 to min(a_i / b_i, r / c_i)
    // Then dp[i][r] = max over k of dp[i-1][r - k*c_i] + k*d_i

    // But we also need to account for plain buns at the end.
    // Actually, we can treat plain buns as another "stuffing" with infinite supply? No, dough is limited.
    // Better: after processing all m stuffings, for each remaining dough r, we can make floor(r / c0) plain buns.
    // So final answer = max over r of dp[m][r] + floor(r / c0) * d0

    // Let's implement with 1D DP to save memory.
    // dp[r] = max profit with r grams of dough remaining after processing some stuffings
    // Start: dp[r] = 0 for all r from 0 to n

    $dp = array_fill(0, $n + 1, 0);

    for ($i = 0; $i < $m; $i++) {
        $a = $stuffings[$i][0];
        $b = $stuffings[$i][1];
        $c = $stuffings[$i][2];
        $d = $stuffings[$i][3];

        $maxBuns = (int)floor($a / $b);

        // new_dp[r] = max over k (0 to min(maxBuns, floor(r/c))) of dp[r - k*c] + k*d
        $newDp = array_fill(0, $n + 1, 0);

        for ($r = 0; $r <= $n; $r++) {
            $best = $dp[$r]; // k = 0
            $maxK = min($maxBuns, (int)floor($r / $c));
            for ($k = 1; $k <= $maxK; $k++) {
                $prevR = $r - $k * $c;
                if ($prevR >= 0) {
                    $val = $dp[$prevR] + $k * $d;
                    if ($val > $best) {
                        $best = $val;
                    }
                }
            }
            $newDp[$r] = $best;
        }
        $dp = $newDp;
    }

    // Now add plain buns
    $maxProfit = 0;
    for ($r = 0; $r <= $n; $r++) {
        $plainBuns = (int)floor($r / $c0);
        $total = $dp[$r] + $plainBuns * $d0;
        if ($total > $maxProfit) {
            $maxProfit = $total;
        }
    }

    echo $maxProfit . "\n";
}

